-- Correct control reference order imported from RTL Excel cells.
do $$
begin
  if exists (
    select 1 from public.controls c join public.frameworks f on f.id=c.framework_id
    where f.code in ('TCC','OSMACC') and (c.control_owner_id is not null or c.implementation_status <> 'not_started' or c.evidence_status <> 'not_uploaded' or c.verification_status <> 'not_verified')
  ) or exists (
    select 1 from public.evidence e join public.controls c on c.id=e.control_id join public.frameworks f on f.id=c.framework_id where f.code in ('TCC','OSMACC')
  ) then raise exception 'TCC/OSMACC controls already contain workflow data; automatic catalog correction stopped';
  end if;
end $$;
delete from public.controls where framework_id in (select id from public.frameworks where code in ('TCC','OSMACC'));
-- Source: NCA TCC Assessment and Compliance Tool v2.0 (TCC-1:2021).
-- Import 63 controls as an unassigned reference catalog.
insert into public.frameworks(code,name_ar,name_en,version,description_ar,is_active)
values ('TCC','ضوابط الأمن السيبراني للعمل عن بعد','Telework Cybersecurity Controls','1-2021','متطلبات تمكين العمل عن بعد بطريقة آمنة والحد من مخاطره السيبرانية.',true)
on conflict (code) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,version=excluded.version,description_ar=excluded.description_ar,is_active=true;
with source(control_code,title_ar,description_ar,domain_ar,control_type,source_row) as (values
    ('1-1-1', 'سياسات وإجراءات الأمن السيبراني - 1-1-1', 'رجوعا للضابط 1-3-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل سياسات وإجراءات الأمن السيبراني ما يأتي:', 'حوكمة الأمن السيبراني', 'أساسي', '10'),
    ('1-1-1-1', 'سياسات وإجراءات الأمن السيبراني - 1-1-1-1', 'تحديد وتوثيق متطلبات وضوابط الأمن السيبراني للعمل عن بعد ضمن سياسات الأمن السيبراني للجهة.', 'حوكمة الأمن السيبراني', 'فرعي', '11'),
    ('1-2-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1', 'بالإضافة للضوابط ضمن المكون الفرعي 1-5 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل منهجية إدارة مخاطر الأمن السيبراني بحد أدنى ما يأتي:', 'حوكمة الأمن السيبراني', 'أساسي', '12'),
    ('1-2-1-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1-1', 'تقييم مخاطر الأمن السيبراني لأنظمة العمل عن بعد، مرة واحدة سنوياً، على الأقل.', 'حوكمة الأمن السيبراني', 'فرعي', '13'),
    ('1-2-1-2', 'إدارة مخاطر الأمن السيبراني - 1-2-1-2', 'تقييم مخاطر الأمن السيبراني عند التخطيط وقبل السماح بالعمل عن بعد لأي خدمة أو نظام.', 'حوكمة الأمن السيبراني', 'فرعي', '14'),
    ('1-2-1-3', 'إدارة مخاطر الأمن السيبراني - 1-2-1-3', 'تضمين مخاطر الأمن السيبراني الخاصة بأنظمة العمل عن بعد والخدمات والأنظمة المسموح لها بالعمل عن بعد في سجل مخاطر الأمن السيبراني الخاص بالجهة، ومتابعته مرة واحدة سنويا، على الأقل.', 'حوكمة الأمن السيبراني', 'فرعي', '15'),
    ('1-3-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-10-3 في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن يغطي برنامج التوعية بالأمن السيبراني المخاطر والتهديدات السيبرانية للعمل عن بعد والاستخدام الآمن للحد من هذه المخاطر والتهديدات، بما في ذلك:', 'حوكمة الأمن السيبراني', 'أساسي', '16'),
    ('1-3-1-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-1', 'الاستخدام الآمن للأجهزة المخصصة للعمل عن بعد والمحافظة عليها وحمايتها.', 'حوكمة الأمن السيبراني', 'فرعي', '17'),
    ('1-3-1-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-2', 'التعامل الآمن مع هويات الدخول وكلمات المرور.', 'حوكمة الأمن السيبراني', 'فرعي', '18'),
    ('1-3-1-3', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-3', 'حماية البيانات التي يتم حفظها على الأجهزة المستخدمة للعمل عن بعد والتعامل معها حسب تصنيفها وإجراءات وسياسات الجهة.', 'حوكمة الأمن السيبراني', 'فرعي', '19'),
    ('1-3-1-4', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-4', 'التعامل الآمن مع التطبيقات والحلول المستخدمة للعمل عن بعد كالاجتماعات الافتراضية، والتعاون ومشاركة الملفات.', 'حوكمة الأمن السيبراني', 'فرعي', '20'),
    ('1-3-1-5', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-5', 'التعامل الآمن مع الشبكات المنزلية والتأكد من إعدادت الحماية الخاصة بها.', 'حوكمة الأمن السيبراني', 'فرعي', '21'),
    ('1-3-1-6', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-6', 'تجنب العمل عن بعد باستخدام أجهزة أو شبكات عامة غير موثوقة أو أثناء التواجد في أماكن عامة.', 'حوكمة الأمن السيبراني', 'فرعي', '22'),
    ('1-3-1-7', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-7', 'الوصول المادي غير المصرح به والفقدان والسرقة والتخريب للأصول التقنية وأنظمة العمل عن بعد.', 'حوكمة الأمن السيبراني', 'فرعي', '23'),
    ('1-3-1-8', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-1-8', 'التواصل مباشرة مع الإدارة المعنية بالأمن السيبراني في الجهة حال الاشتباه بتهديد أمن سيبراني.', 'حوكمة الأمن السيبراني', 'فرعي', '24'),
    ('1-3-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-3-2', 'بالإضافة للضوابط الفرعية ضمن الضابط 1-10-4 في الضوابط الأساسية للأمن السيبراني، فإنه يجب تدريب العاملين على المهارات التقنية اللازمة لضمان تطبيق متطلبات وممارسات الأمن السيبراني عند التعامل مع أنظمة العمل عن بعد.', 'حوكمة الأمن السيبراني', 'أساسي', '25'),
    ('2-1-1', 'إدارة الأصول - 2-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي 2-1 في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '26'),
    ('2-1-1-1', 'إدارة الأصول - 2-1-1-1', 'تحديد وحصر الأصول المعلوماتية والتقنية لأنظمة العمل عن بعد، وتحديثها مرة واحدة، كل سنة؛ على الأقل.', 'تعزيز الأمن السيبراني', 'فرعي', '27'),
    ('2-2-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-2-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول، والصلاحيات للأنظمة المستخدمة في العمل عن بعد في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '28'),
    ('2-2-1-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1-1', 'إدارة صلاحيات المستخدمين للعمل عن بعد بناءً على احتياجات العمل، مع مراعاة حساسية الأنظمة ومستوى الصلاحيات، ونوعية الأجهزة المستخدمة من قبل الموظفين للعمل عن بعد.', 'تعزيز الأمن السيبراني', 'فرعي', '29'),
    ('2-2-1-2', 'إدارة هويات الدخول والصلاحيات - 2-2-1-2', 'تقييد إمكانية الوصول عن بعد لنفس المستخدم من أجهزة حاسبات متعددة في نفس الوقت (Concurrent Logins).', 'تعزيز الأمن السيبراني', 'فرعي', '30'),
    ('2-2-1-3', 'إدارة هويات الدخول والصلاحيات - 2-2-1-3', 'استخدام معايير آمنة لإدارة الهويات وكلمات المرور المستخدمة في أنظمة العمل عن بعد.', 'تعزيز الأمن السيبراني', 'فرعي', '31'),
    ('2-2-2', 'إدارة هويات الدخول والصلاحيات - 2-2-2', 'رجوعاً للضابط الفرعي2-2-3-5 في الضوابط الأساسية للأمن السيبراني، يجب مراجعة هويات الدخول والصلاحيات المستخدمة للعمل عن بعد، بحد أدنى مرة واحدة كل سنة.', 'تعزيز الأمن السيبراني', 'أساسي', '32'),
    ('2-3-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-3-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية أنظمة العمل عن بعد، وأجهزة المعلومات الخاصة بها، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '33'),
    ('2-3-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-1', 'تطبيق حزم التحديثات، والإصلاحات الأمنية لأنظمة العمل عن بعد، مرة واحدة شهريا على الأقل.', 'تعزيز الأمن السيبراني', 'فرعي', '34'),
    ('2-3-1-2', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-2', 'مراجعة إعدادات الحماية لأنظمة العمل عن بعد والتحصين (Secure Configuration and Hardening)، مرة واحدة كل سنة على الأقل.', 'تعزيز الأمن السيبراني', 'فرعي', '35'),
    ('2-3-1-3', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-3', 'مراجعة وتحصين الإعدادت المصنعية (Default Configuration) للأصول التقنية لأنظمة العمل عن بعد، ومنها وجود كلمات مرور ثابتة، وخلفية افتراضية.', 'تعزيز الأمن السيبراني', 'فرعي', '36'),
    ('2-3-1-4', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-4', 'الإدارة الآمنة للجلسات (Secure Session Management)، ويشمل موثوقية الجلسات (Authenticity)، وإقفالها (Lockout)، وإنهاء مهلتها (Timeout).', 'تعزيز الأمن السيبراني', 'فرعي', '37'),
    ('2-3-1-5', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-5', 'تقييد تفعيل الخصائص والخدمات في أنظمة العمل عن بعد حسب الحاجة، على أن يتم تحليل المخاطر السيبرانية المحتملة في حال الحاجة لتفعيلها.', 'تعزيز الأمن السيبراني', 'فرعي', '38'),
    ('2-4-1', 'إدارة أمن الشبكات - 2-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-5-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة للعمل عن بعد، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '39'),
    ('2-4-1-1', 'إدارة أمن الشبكات - 2-4-1-1', 'تقييد منافذ وبروتوكولات وخدمات الشبكة المستخدمة لعمليات الدخول عن بعد، وخصوصاً على الأنظمة الداخلية، وفتحها حسب الحاجة.', 'تعزيز الأمن السيبراني', 'فرعي', '40'),
    ('2-4-1-2', 'إدارة أمن الشبكات - 2-4-1-2', 'مراجعة إعدادات وقوائم جدار الحماية (Firewall Rules) ذات العلاقة بأنظمة العمل عن بعد؛ مرة واحدة كل سنة على الأقل.', 'تعزيز الأمن السيبراني', 'فرعي', '41'),
    ('2-4-1-3', 'إدارة أمن الشبكات - 2-4-1-3', 'الحماية من هجمات تعطيل الشبكات Distrbuted Denial of Service Attack (DDoS) على أنظمة العمل عن بعد للحد من المخاطر الناتجة عن هجمات تعطيل الشبكات.', 'تعزيز الأمن السيبراني', 'فرعي', '42'),
    ('2-4-1-4', 'إدارة أمن الشبكات - 2-4-1-4', 'الحماية من التهديدات المتقدمة المستمرة على مستوى الشبكة لأنظمة العمل عن بعد (Network APT).', 'تعزيز الأمن السيبراني', 'فرعي', '43'),
    ('2-5-1', 'أمن الأجهزة المحمولة - 2-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-6-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة للعمل عن بعد في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '44'),
    ('2-5-1-1', 'أمن الأجهزة المحمولة - 2-5-1-1', 'إدارة الأجهزة المحمولة وأجهزة (BYOD) مركزياً باستخدام نظام إدارة الأجهزة المحمولة (Mobile Device Management - MDM).', 'تعزيز الأمن السيبراني', 'فرعي', '45'),
    ('2-5-1-2', 'أمن الأجهزة المحمولة - 2-5-1-2', 'تطبيق حزم التحديثات، والإصلاحات الأمنية للأجهزة المحمولة، مرة واحدة شهريا، على الأقل.', 'تعزيز الأمن السيبراني', 'فرعي', '46'),
    ('2-6-1', 'حماية البيانات والمعلومات - 2-6-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-7-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية البيانات والمعلومات للعمل عن بعد في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '47'),
    ('2-6-1-1', 'حماية البيانات والمعلومات - 2-6-1-1', 'تحديد البيانات المصنفة، حسب التشريعات ذات العلاقة، التي يمكن استخدامها أو الوصول إليها أو التعامل معها من خلال أنظمة العمل عن بعد.', 'تعزيز الأمن السيبراني', 'فرعي', '48'),
    ('2-6-1-2', 'حماية البيانات والمعلومات - 2-6-1-2', 'حماية البيانات المصنفة، التي تم تحديدها في الضابط 2-6-1-1، باستخدام ضوابط مثل منع استخدام نوع من البيانات المصنفة أو تقنيات مثل منع تسريب البيانات (Data Leakage Prevention). ويمكن تحديد هذه الضوابط والتقنيات عن طريق تحليل المخاطر السيبرانية للجهة.', 'تعزيز الأمن السيبراني', 'فرعي', '49'),
    ('2-7-1', 'التشفير - 2-7-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-8-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني للتشفير في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '50'),
    ('2-7-1-1', 'التشفير - 2-7-1-1', 'استخدام طرق وخوارزميات محدثة وآمنة للتشفير على كامل الاتصال الشبكي المستخدم للعمل عن بعد وفقاً للمستوى المتقدم (Advanced) ضمن المعايير الوطنية للتشفير (NCS - 1:2020).', 'تعزيز الأمن السيبراني', 'فرعي', '51'),
    ('2-8-1', 'إدارة النسخ الاحتياطية - 2-8-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-9-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية لأنظمة العمل عن بعد في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '52'),
    ('2-8-1-1', 'إدارة النسخ الاحتياطية - 2-8-1-1', 'عمل النسخ الاحتياطي على فترات زمنية مخطط لها؛ بناء على تقييم المخاطر للجهة، لأنظمة العمل عن بعد. وتوصي الهيئة بأن يتم عمل النسخ الاحتياطية، لأنظمة العمل عن بعد مرة واحدة كل أسبوع.', 'تعزيز الأمن السيبراني', 'فرعي', '53'),
    ('2-8-2', 'إدارة النسخ الاحتياطية - 2-8-2', 'رجوعاً للضابط 2-9-3-3 في الضوابط الأساسية للأمن السيبراني، يجب إجراء فحص دوري؛ كل ستة أشهر على الأقل، لتحديد مدى فعالية استعادة النسخ الاحتياطية، الخاصة بأنظمة العمل عن بعد.', 'تعزيز الأمن السيبراني', 'أساسي', '54'),
    ('2-9-1', 'إدارة الثغرات - 2-9-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-10-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة الثغرات للأصول التقنية وأنظمة العمل عن بعد، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '55'),
    ('2-9-1-1', 'إدارة الثغرات - 2-9-1-1', 'فحص الثغرات واكتشافها على أنظمة العمل عن بعد وتصنيفها حسب خطورتها، مرة واحدة كل ثلاثة أشهر على الأقل.', 'تعزيز الأمن السيبراني', 'فرعي', '56'),
    ('2-9-1-2', 'إدارة الثغرات - 2-9-1-2', 'معالجة الثغرات على أنظمة العمل عن بعد، مرة واحدة كل ثلاثة أشهر على الأقل.', 'تعزيز الأمن السيبراني', 'فرعي', '57'),
    ('2-10-1', 'اختبار الاختراق - 2-10-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-11-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لاختبار الاختراق لأنظمة العمل عن بعد، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', '58'),
    ('2-10-1-1', 'اختبار الاختراق - 2-10-1-1', 'نطاق عمل اختبار الاختراق، ليشمل جميع المكونات التقنية لأنظمة العمل عن بعد.', 'تعزيز الأمن السيبراني', 'فرعي', '59'),
    ('2-10-2', 'اختبار الاختراق - 2-10-2', 'رجوعاً للضابط 2-11-3-2 في الضوابط الأساسية للأمن السيبراني، يجب عمل اختبار الاختراق على أنظمة العمل عن بعد مرة واحدة كل سنة على الأقل.', 'تعزيز الأمن السيبراني', 'أساسي', '60'),
    ('2-11-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-12-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة سجلات الأحداث، ومراقبة الأمن السيبراني للأصول التقنية وأنظمة العمل عن بعد، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '61'),
    ('2-11-1-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-1', 'تفعيل سجلات الأحداث (Event Logs) الخاصة بالأمن السيبراني على الأصول التقنية وأنظمة العمل عن بعد.', 'تعزيز الأمن السيبراني', 'فرعي', '62'),
    ('2-11-1-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-2', 'مراقبة سلوك مستخدمي أنظمة العمل عن بعد', 'تعزيز الأمن السيبراني', 'فرعي', '63'),
    ('2-11-1-3', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-3', 'مراقبة سجلات الأحداث، الخاصة بالأصول التقنية وأنظمة العمل عن بعد على مدار الساعة.', 'تعزيز الأمن السيبراني', 'فرعي', '64'),
    ('2-11-1-4', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-4', 'تحديث إجراءات مراقبة الأمن السيبراني على مدار الساعة وتطبيقها، بحيث تشمل مراقبة عمليات الدخول عن بعد، ولاسيما عمليات الدخول عن بعد من خارج المملكة والتحقق من صحتها.', 'تعزيز الأمن السيبراني', 'فرعي', '65'),
    ('2-11-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-2', 'رجوعاً للضابط 2-12-3-5 في الضوابط الأساسية للأمن السيبراني، يجب ألا تقل مدة الاحتفاظ بسجلات الأحداث الخاصة بالأمن السيبراني لأنظمة العمل عن بعد عن 12 شهراً؛ حسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'تعزيز الأمن السيبراني', 'أساسي', '66'),
    ('2-12-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 2-13-3 في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة حوادث وتهديدات الأمن السيبراني في الجهة، بحد أدنى، مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', '67'),
    ('2-12-1-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-1-1', 'تحديث خطط الاستجابة لحوادث الأمن السيبراني ومعلومات التواصل داخل الجهة بما يتوافق مع حالة العمل عن بعد، وبما يضمن القدرة على التواصل وجاهزية فرق الاستجابة للحوادث.', 'تعزيز الأمن السيبراني', 'فرعي', '68'),
    ('2-12-1-2', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-1-2', 'الحصول على المعلومات الاستباقية (Threat Intelligence) ذات العلاقة بأنظمة العمل عن بعد بشكل دوري والتعامل معها.', 'تعزيز الأمن السيبراني', 'فرعي', '69'),
    ('2-12-1-3', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-12-1-3', 'تنفيذ وتطبيق التوصيات والتنبيهات الخاصة بحوادث وتهديدات الأمن السيبراني الصادرة من مشرف القطاع أو الهيئة الوطنية للأمن السيبراني.', 'تعزيز الأمن السيبراني', 'فرعي', '70'),
    ('3-1-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 3-1-1', 'بالإضافة للضوابط الفرعية ضمن الضابط 4-2-3 في الضوابط الأساسية للأمن السيراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة، بحد أدنى، ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'أساسي', '71'),
    ('3-1-1-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 3-1-1-1', 'موقع استضافة أنظمة العمل عن بعد يجب أن يكون داخل المملكة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', '72')
), framework as (select id from public.frameworks where code='TCC')
insert into public.controls(framework_id,control_code,title_ar,description_ar,domain_ar,implementation_status,evidence_status,verification_status)
select framework.id,source.control_code,source.title_ar,source.description_ar,source.domain_ar,'not_started','not_uploaded','not_verified' from source cross join framework
on conflict (framework_id,control_code) do update set title_ar=excluded.title_ar,description_ar=excluded.description_ar,domain_ar=excluded.domain_ar;

-- Source: NCA OSMACC Assessment and Compliance Tool v1.0 (OSMACC-1:2021).
-- Import 49 controls as an unassigned reference catalog.
insert into public.frameworks(code,name_ar,name_en,version,description_ar,is_active)
values ('OSMACC','ضوابط الأمن السيبراني لحسابات التواصل الاجتماعي للجهات','Organizations Social Media Accounts Cybersecurity Controls','1-2021','متطلبات حماية حسابات التواصل الاجتماعي الرسمية للجهات من السرقة وسوء الاستغلال والانتحال.',true)
on conflict (code) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,version=excluded.version,description_ar=excluded.description_ar,is_active=true;
with source(control_code,title_ar,description_ar,domain_ar,control_type,source_row) as (values
    ('1-1-1', 'سياسات وإجراءات الأمن السيبراني - 1-1-1', 'رجوعــاً للضابــط 1-3-1 في الضوابــط الأساســية للأمــن الســيبراني، يجــب أن تشــمل سياســات وإجــراءات الأمــن الســيبراني مــا يــأتي: 1-1-1-1 تحديــد وتوثيــق متطلبــات وضوابــط الأمــن الســيبراني لحســابات التواصــل الاجتماعــي ضمــن سياســات الأمــن الســيبراني للجهــة.', 'حوكمة الأمن السيبراني', 'أساسي', '10'),
    ('1-2-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1', 'بالإضافـة للضوابـط ضمـن المكـون الفرعـي 1-5 في الضوابـط الأساسـية للأمـن السـيبراني، يجـب أن تشـمل منهجيـة إدارة مخاطـر الأمـن الســيبراني بحـد أدنى مـا يـأتي:', 'حوكمة الأمن السيبراني', 'أساسي', '11'),
    ('1-2-1-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1-1', 'تقييــم مخاطــر الأمــن الســيبراني لحســابات التواصــل الاجتماعــي، مــرة واحــدة ســنوياً، عــلى الأقــل.', 'حوكمة الأمن السيبراني', 'فرعي', '12'),
    ('1-2-1-2', 'إدارة مخاطر الأمن السيبراني - 1-2-1-2', 'تقييـم مخاطـر الأمـن السـيبراني عنـد التخطيـط وقبـل السـماح باسـتخدام شـبكات التواصــل الاجتماعي.', 'حوكمة الأمن السيبراني', 'فرعي', '13'),
    ('1-2-1-3', 'إدارة مخاطر الأمن السيبراني - 1-2-1-3', 'تضميــن مخاطــر الأمــن الســيبراني الخاصــة بحســابات التواصــل الاجتماعــي والخدمــات والأنظمــة المســتخدمة في ذلــك في ســجل مخاطــر الأمــن الســيبراني الخــاص بالجهــة، ومتابعتــه مــرة واحــدة ســنوياً، علــى الأقــل.', 'حوكمة الأمن السيبراني', 'فرعي', '14'),
    ('1-3-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-3-1', 'بالإضافـة للضوابـط الفرعيــة ضمــن الضابــط 1-9- 4 في الضوابـط الأساسـية للأمـن السـيبراني، يجـب أن تشـمل متطلبـات الأمـن السـيبراني المتعلقـة بالعاملـين المسـؤولين عـن إدارة حسـابات التواصـل الاجتماعـي للجهـة بحـد أدنى مـا يـأتي:', 'حوكمة الأمن السيبراني', 'أساسي', '15'),
    ('1-3-1-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-3-1-1', 'التوعية بالأمن السيبراني لحسابات التواصل الاجتماعي.', 'حوكمة الأمن السيبراني', 'فرعي', '16'),
    ('1-3-1-2', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-3-1-2', 'تطبيـق متطلبـات الأمــن السـيبراني والالـتــزام بهـا وفقـاً لسياسـات وإجــــراءات وعمليــات الأمــن الســيبراني لحســابات التواصــل الاجتماعــي.', 'حوكمة الأمن السيبراني', 'فرعي', '17'),
    ('1-4-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1', 'بالإضافـة للضوابـط الفرعيـة ضمـن الضابـط 1-10-3 في الضوابـط الأساسـية للأمـن السـيبراني، فإنه يجـب أن يغطـي برنامـج التوعيـة بالأمـن السـيبراني المخاطـر والتهديـدات السـيبرانية لحسـابات التواصـل الاجتماعـي والاسـتخدام الآمـن للحـد مـن هـذه المخاطـر والتهديـدات، بمـا في ذلـك:', 'حوكمة الأمن السيبراني', 'أساسي', '18'),
    ('1-4-1-1', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-1', 'الاسـتخدام الآمـن للأجهـزة المخصصـة لحسـابات التواصـل الاجتماعـي والمحافظـة عليهـا وحمايتهـا. وعـدم احتوائهـا عـلى بيانـات مصنفـة أو اسـتخدامها لأغـراض شـخصية.', 'حوكمة الأمن السيبراني', 'فرعي', '19'),
    ('1-4-1-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-2', 'التعامل الآمن مع هويات الدخول وكلمات المرور والأسئلة الأمنية.', 'حوكمة الأمن السيبراني', 'فرعي', '20'),
    ('1-4-1-3', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-3', 'خطة استعادة حسابات التواصل الاجتماعي والتعامل مع الحوادث السيبرانية.', 'حوكمة الأمن السيبراني', 'فرعي', '21'),
    ('1-4-1-4', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-4', 'التعامــل الآمــن مــع التطبيقــات والحلــول المســتخدمة لحســابات التواصــل الاجتماعــي.', 'حوكمة الأمن السيبراني', 'فرعي', '22'),
    ('1-4-1-5', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-5', 'عـدم اسـتخدام حسـابات التواصـل الاجتماعـي الرسـمية لأغـراض شـخصية مثـل التصفـح.', 'حوكمة الأمن السيبراني', 'فرعي', '23'),
    ('1-4-1-6', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-6', 'تجنــب الدخــول لحســابات التواصــل الاجتماعــي باســتخدام أجهــزة أو شــبكات عامـة غيـر موثوقـة.', 'حوكمة الأمن السيبراني', 'فرعي', '24'),
    ('1-4-1-7', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-1-7', 'التواصــل مبــاشرة مــع الإدارة المعنيــة بالأمــن الســيبراني في الجهــة حــال الاشــتباه بتهديـد أمـن سـيبراني.', 'حوكمة الأمن السيبراني', 'فرعي', '25'),
    ('1-4-2', 'برنامج التوعية والتدريب بالأمن السيبراني - 1-4-2', 'بالإضافـة للضوابـط الفرعيـة ضمـن الضابـط 1-10-4 في الضوابـط الأساسـية للأمـن السـيبراني، فإنـه يجـب تدريـب العاملـين المسـؤولين عـن إدارة حسـابات التواصـل الاجتماعـي للجهـة عـلى المهــارات التقنيــة والخطــط والإجــراءات اللازمــة لضــمان تطبيــق متطلبــات وممارســات الأمــن الســيبراني عنــد اســتخدام حســابات التواصــل الاجتماعــي.', 'حوكمة الأمن السيبراني', 'أساسي', '26'),
    ('2-1-1', 'إدارة الأصول - 2-1-1', 'بالإضافـة للضوابـط ضمـن المكـون الفرعـي 2-1 في الضوابـط الأساسـية للأمـن السـيبراني، يجـب أن تشـمل متطلبـات الأمـن السـيبراني لإدارة الأصـول المعلوماتيـة والتقنيـة، بحـد أدنى، مايلـي: 2-1-1-1 يجــب تحديــد وحصــر حســابات التواصــل الاجتماعــي والأصــول المعلوماتيــة والتقنيــة المتعلقــة بهــا، وتحديثهــا مــرة واحــدة، كل ســنة؛ عــلى الأقــل.', 'تعزيز الأمن السيبراني', 'أساسي', '27'),
    ('2-2-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1', 'بالإضافـة للضوابـط الفرعيـة ضمـن الضابـط 2-2-3 في الضوابـط الأساسـية للأمـن السـيبراني، يجـب أن تغطـي متطلبـات الأمـن السـيبراني المتعلقـة بـإدارة هويـات الدخـول، والصلاحيـات لحسـابات التواصـل الاجتماعـي للجهـة، بحـد أدنى، مايـلي:', 'تعزيز الأمن السيبراني', 'أساسي', '28'),
    ('2-2-1-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1-1', 'استخدام حسابات التواصل الاجتماعي المخصصة للجهات، وليس الأفراد.', 'تعزيز الأمن السيبراني', 'فرعي', '29'),
    ('2-2-1-2', 'إدارة هويات الدخول والصلاحيات - 2-2-1-2', 'التسـجيل باسـتخدام معلومـات رسـمية (بريـد إلكتـروني رسـمي خـاص لوسـائل التواصـل الاجتماعـي ورقـم جـوال رسـمي)، وعـدم اسـتخدام معلومات شـخصية.', 'تعزيز الأمن السيبراني', 'فرعي', '30'),
    ('2-2-1-3', 'إدارة هويات الدخول والصلاحيات - 2-2-1-3', 'توثيــق حســابات التواصــل الاجتماعــي والمحافظــة عــلى هويــة متســقة في جميـع حسـابات التواصـل الاجتماعـي المسـتخدمة؛ لتسـهيل معرفـة الحسـابات الرســمية، واكتشــاف حســابات الاحتيــال.', 'تعزيز الأمن السيبراني', 'فرعي', '31'),
    ('2-2-1-4', 'إدارة هويات الدخول والصلاحيات - 2-2-1-4', 'اســتخدام كلمــة مــرور آمنــة وخاصــة لــكل حســابات التواصــل الاجتماعــي. وتغييــر كلمــة المــرور بشــكل دوري، وعــدم إعــادة اســتخدام كلمــة مــرور تــم اســتخدامها مــن قبــل.', 'تعزيز الأمن السيبراني', 'فرعي', '32'),
    ('2-2-1-5', 'إدارة هويات الدخول والصلاحيات - 2-2-1-5', 'اســتخدام التحقــق مــن الهويــة متعــدد العنــاصر (Multi-Factor Authentication) لعمليــات الدخــول لحســابات التواصــل الاجتماعــي.', 'تعزيز الأمن السيبراني', 'فرعي', '33'),
    ('2-2-1-6', 'إدارة هويات الدخول والصلاحيات - 2-2-1-6', 'تفعيل وتحديث الأسئلة الأمنية وتوثيقها في مكان آمن.', 'تعزيز الأمن السيبراني', 'فرعي', '34'),
    ('2-2-1-7', 'إدارة هويات الدخول والصلاحيات - 2-2-1-7', 'إدارة صلاحيــات المســتخدمين لحســابات التواصــل الاجتماعــي بنــاءً علــى احتياجــات العمــل، مــع مراعــاة حساســية الحســابات ومســتوى الصلاحيــات، ونوعيــة الأجهــزة والأنظمــة المســتخدمة.', 'تعزيز الأمن السيبراني', 'فرعي', '35'),
    ('2-2-1-8', 'إدارة هويات الدخول والصلاحيات - 2-2-1-8', 'حـصر صلاحيـات مقدمـي خدمـة إدارة حسـابات التواصـل الاجتماعـي أو المراقبة الآليـة لحسـابات التواصـل الاجتماعـي أو حمايـة هويـة الجهـة مـن الانتحال.', 'تعزيز الأمن السيبراني', 'فرعي', '36'),
    ('2-2-1-9', 'إدارة هويات الدخول والصلاحيات - 2-2-1-9', 'حــصر إمكانيــة الدخــول لحســابات التواصــل الاجتماعــي للجهــة مــن أجهــزة محــددة.', 'تعزيز الأمن السيبراني', 'فرعي', '37'),
    ('2-2-2', 'إدارة هويات الدخول والصلاحيات - 2-2-2', 'رجوعـاً للضابـط الفرعـي 2-2-3-5 في الضوابـط الأساسـية للأمـن السـيبراني، يجـب مراجعـة هويات الدخـول والصلاحيـات المسـتخدمة لحسـابات التواصـل الاجتماعـي للجهـة، بحـد أدنى مـرة واحـدة كل سـنة.', 'تعزيز الأمن السيبراني', 'أساسي', '38'),
    ('2-3-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1', 'بالإضافـة للضوابـط الفرعيـة ضمـن الضابـط 2-3-3 في الضوابـط الأساسـية للأمـن السـيبراني، يجـب أن تغطـي متطلبـات الأمـن السـيبراني لحمايـة حسـابات التواصـل الاجتماعـي للجهـة، والأصـول التقنيـة الخاصـة بهـا، بحـد أدنى، مايـلي:', 'تعزيز الأمن السيبراني', 'أساسي', '39'),
    ('2-3-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-1', 'تطبيـق حـزم التحديثـات، والإصلاحـات الأمنيـة لتطبيقـات التواصـل الاجتماعـي، مـرة واحـدة شـهرياً عــلى الأقـل.', 'تعزيز الأمن السيبراني', 'فرعي', '40'),
    ('2-3-1-2', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-2', 'مراجعـة إعـدادات الحمايـة والتحصـين لحسـابات التواصـل الاجتماعـي للجهـة والأصــول التقنيــة الخاصــة بهــا (Secure Configuration and Hardening)، مـرة واحـدة كل سـنة علـى الأقـل.', 'تعزيز الأمن السيبراني', 'فرعي', '41'),
    ('2-3-1-3', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-3', 'مراجعـة وتحصيـن الإعـدادات المصنعيـة (Default Configuration) لحسـابات التواصــل الاجتماعــي والأصــول التقنيــة، ومنهــا وجــود كلــمات مــرور ثابتــة أو تسـجيل الدخـول المسـبق، وإقفـال الأجهـزة (Lockout).', 'تعزيز الأمن السيبراني', 'فرعي', '42'),
    ('2-3-1-4', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-4', 'تقييـد تفعيـل الخصائـص والخدمـات في حسـابات التواصـل الاجتماعـي حسـب الحاجــة، عـلـى أن يتــم تحليــل المخاطــر الســيبرانية المحتملــة في حــال الحاجــة لتفعيلهـا.', 'تعزيز الأمن السيبراني', 'فرعي', '43'),
    ('2-4-1', 'أمن الأجهزة المحمولة - 2-4-1', 'بالإضافـة للضوابـط الفرعيـة ضمـن الضابـط 2-6-3 في الضوابـط الأساسـية للأمـن السـيبراني، يجـب أن تغطــي متطلبــات الأمــن الســيبراني الخاصــة بأمــن الأجهــزة المحمولــة لحســابات التواصــل الاجتماعـي للجهـة، بحـد أدنى، مايـلي:', 'تعزيز الأمن السيبراني', 'أساسي', '44'),
    ('2-4-1-1', 'أمن الأجهزة المحمولة - 2-4-1-1', 'إدارة الأجهــزة المحمولــة مركزيــاً باســتخدام نظــام إدارة الأجهــزة المحمولــة (Mobile Device Management - MDM).', 'تعزيز الأمن السيبراني', 'فرعي', '45'),
    ('2-4-1-2', 'أمن الأجهزة المحمولة - 2-4-1-2', 'تطبيـق حـزم التحديثـات، والإصلاحـات الأمنيـة للأجهـزة المحمولـة، مـرة واحـدة شـهرياً، علـى الأقـل.', 'تعزيز الأمن السيبراني', 'فرعي', '46'),
    ('2-5-1', 'حماية البيانات والمعلومات - 2-5-1', 'بالإضافــة للضوابــط الفرعيــة ضمــن الضابــط 2-7-3 في الضوابــط الأساســية للأمــن الســيبراني، يجـب أن تغطـي متطلبـات الأمـن السـيبراني لحمايـة البيانـات والمعلومـات لحسـابات التواصـل الاجتماعــي للجهــة، بحــد أدنى، مايــلي: 2-5-1-1 يجــب أن لا تحتــوي الأصــول التقنيــة الخاصــة بحســابات التواصــل الاجتماعــي للجهــة عــلى بيانــات مصنفــة، حســب التشريعــات ذات العلاقــة.', 'تعزيز الأمن السيبراني', 'أساسي', '47'),
    ('2-6-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-6-1', 'بالإضافــة للضوابــط الفرعيــة ضمــن الضابــط 2-12-3 في الضوابــط الأساســية للأمــن الســيبراني، يجـب أن تغطـي متطلبـات إدارة سـجلات الأحـداث، ومراقبـة الأمـن السـيبراني لحسـابات التواصـل الاجتماعـي للجهـة والأصـول التقنيـة التابعـة لهـا، بحـد أدنى، مايلـي:', 'تعزيز الأمن السيبراني', 'أساسي', '48'),
    ('2-6-1-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-6-1-1', 'تفعيـل جميـع الإشـعارات وتنبيهـات الأمـن السـيبراني الخاصة بحسـابات التواصل الاجتماعـي وسـجلات الأحـداث (Event Logs) الخاصـة بالأمـن السـيبراني عـلى الأصـول التقنيـة الخاصـة بحسـابات التواصـل الاجتماعـي.', 'تعزيز الأمن السيبراني', 'فرعي', '49'),
    ('2-6-1-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-6-1-2', 'متابعــة حســابات التواصــل الاجتماعــي ومراقبتهــا للتأكــد مــن عــدم نــشر أي محتــوى غيــر مــصرح، أو تســجيل أي دخــول غــر مصــرح.', 'تعزيز الأمن السيبراني', 'فرعي', '50'),
    ('2-6-1-3', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-6-1-3', 'متابعـة شـبكات التواصـل الاجتماعـي ومراقبتهـا للتأكـد مـن عـدم انتحـال هويـة الجهة.', 'تعزيز الأمن السيبراني', 'فرعي', '51'),
    ('2-6-1-4', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-6-1-4', 'المراقبــة الآليــة لأي تغيــر في نمــط الحســابات أو مــؤشرات اخـتـراق أو نــشر أي محتـوى غـير مصـرح أو انتحـال هويـة الجهـة.', 'تعزيز الأمن السيبراني', 'فرعي', '52'),
    ('2-7-1', 'إدارة حوادث وتهديدات الأمن السيبراني - 2-7-1', 'بالإضافـة للضوابـط الفرعيـة ضمـن الضابـط 2-13-3 في الضوابـط الأساسـية للأمـن السـيبراني، يجب أن تغطـي متطلبـات إدارة حـوادث وتهديـدات الأمـن السـيبراني في الجهـة، بحـد أدنى، مايلي: 2-7-1-1 وضــع خطــة اســتعادة حســابات التواصــل الاجتماعــي والتعامــل مــع الحــوادث الســيبرانية.', 'تعزيز الأمن السيبراني', 'أساسي', '53'),
    ('3-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-1', 'يجــب تقييــم مــدى الحاجــة لاســتخدام خدمــات إدارة حســابات التواصــل الاجتماعــي (social media management) والمراقبـة الآليـة لحسـابات التواصـل الاجتماعـي أو لحمايـة هويـة الجهـة مـن الانتحـال (brand protection) ومخاطـر الأمـن السـيبراني المتعلقـة بهـا.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'أساسي', '54'),
    ('3-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2', 'بالإضافــة للضوابــط الفرعيــة ضمــن الضابــط 4-1-2 في الضوابــط الأساســية للأمــن الســيبراني، يجـب أن تغطـي متطلبـات الأمـن السـيبراني الخاصـة باسـتخدام خدمـات إدارة حسـابات التواصـل الاجتماعـي (social media management) والمراقبــة الآليـة لحسـابات التواصـل الاجتماعـي أو لحمايـة هويـة الجهـة مـن الانتحـال (brand protection)، بحـد أدنى، مـا يـلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'أساسي', '55'),
    ('3-1-2-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-1', 'بنــود المحافظــة عــلى سريــة المعلومــات (Non-Disclosure Clauses) والحــذف الآمـن مـن قبـل الطـرف الخارجـي لبيانـات الجهـة عنـد انتهـاء الخدمـة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', '56'),
    ('3-1-2-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-2', 'إجراءات التواصل للإبلاغ عن الثغرات وفي حال اكتشاف حادثة أمن سيبراني.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', '57'),
    ('3-1-2-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 3-1-2-3', 'إلــزام الطــرف الخارجــي بتطبيــق متطلبــات وسياســات الأمــن الســيبراني لحمايــة حســابات التواصــل الاجتماعــي للجهــة والمتطلبــات التشريعيــة والتنظيميــة ذات العلاقــة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', '58')
), framework as (select id from public.frameworks where code='OSMACC')
insert into public.controls(framework_id,control_code,title_ar,description_ar,domain_ar,implementation_status,evidence_status,verification_status)
select framework.id,source.control_code,source.title_ar,source.description_ar,source.domain_ar,'not_started','not_uploaded','not_verified' from source cross join framework
on conflict (framework_id,control_code) do update set title_ar=excluded.title_ar,description_ar=excluded.description_ar,domain_ar=excluded.domain_ar;
